package main

import("encoding/csv";"encoding/json";"io";"net/http";"strings";"time";"go.mau.fi/whatsmeow/types")
func ensureBulkMessageTable()error{_,err:=userDB.Exec(`CREATE TABLE IF NOT EXISTS public.bulk_messages(id BIGSERIAL PRIMARY KEY,user_id TEXT,target TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,assigned_sender TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),sent_at TIMESTAMPTZ); ALTER TABLE public.bulk_messages ADD COLUMN IF NOT EXISTS assigned_sender TEXT; ALTER TABLE public.bulk_messages ALTER COLUMN user_id DROP NOT NULL; CREATE INDEX IF NOT EXISTS bulk_messages_queue_idx ON public.bulk_messages(status,id)`);return err}
func bulkConnectedDevices()[]string{manager.mu.RLock();defer manager.mu.RUnlock();ids:=make([]string,0,len(manager.sessions));for uid,s:=range manager.sessions{if s!=nil&&s.client!=nil&&s.client.IsLoggedIn()&&s.client.IsConnected(){ids=append(ids,uid)}};return ids}
func bulkMessageImportHandler(w http.ResponseWriter,r *http.Request){enableCORS(w);w.Header().Set("Content-Type","application/json");if r.Method!=http.MethodPost{w.WriteHeader(http.StatusMethodNotAllowed);return};if err:=ensureBulkMessageTable();err!=nil{w.WriteHeader(http.StatusInternalServerError);return};if strings.HasPrefix(r.Header.Get("Content-Type"),"application/json"){var in struct{Action string `json:"action"`;UserIDs []string `json:"user_ids"`;Limit int `json:"limit"`};if err:=json.NewDecoder(r.Body).Decode(&in);err!=nil{w.WriteHeader(http.StatusBadRequest);_=json.NewEncoder(w).Encode(APIResponse{Status:"error",Message:"Invalid request"});return};if in.Action!="send"{w.WriteHeader(http.StatusBadRequest);_=json.NewEncoder(w).Encode(APIResponse{Status:"error",Message:"Unknown action"});return};limit:=in.Limit;if limit<1{limit=20};if limit>200{limit=200};allowed:=make(map[string]bool);if len(in.UserIDs)==0{for _,uid:=range bulkConnectedDevices(){allowed[uid]=true}}else{for _,uid:=range in.UserIDs{uid=strings.TrimSpace(uid);s:=getSession(uid);if s!=nil&&s.client!=nil&&s.client.IsLoggedIn()&&s.client.IsConnected(){allowed[uid]=true}}};if len(allowed)==0{w.WriteHeader(http.StatusServiceUnavailable);_=json.NewEncoder(w).Encode(APIResponse{Status:"error",Message:"No connected WhatsApp accounts selected"});return};sent,attempted:=0,0;for attempted<limit{uid:=nextBulkSender(allowed,attempted);id,target,text,ok:=claimBulkRow(uid);if !ok{break};attempted++;s:=getSession(uid);if s==nil||s.client==nil{markBulkFailed(id,"WhatsApp account disconnected");continue};s.mu.Lock();err:=safeSendMessage(uid,s.client,types.JID{User:target,Server:types.DefaultUserServer},text);s.mu.Unlock();if err!=nil{markBulkFailed(id,err.Error());continue};_,_=userDB.Exec(`UPDATE public.bulk_messages SET status='sent',sent_at=now(),last_error=NULL WHERE id=$1`,id);sent++};_=json.NewEncoder(w).Encode(map[string]any{"status":"success","attempted":attempted,"sent":sent,"message":"Manual bulk send completed with per-account safety controls."});return};r.Body=http.MaxBytesReader(w,r.Body,512<<20);mr,err:=r.MultipartReader();if err!=nil{w.WriteHeader(http.StatusBadRequest);return};var file io.Reader;for{part,e:=mr.NextPart();if e==io.EOF{break};if e!=nil{w.WriteHeader(http.StatusBadRequest);return};if part.FormName()=="file"{file=part;break}};if file==nil{w.WriteHeader(http.StatusBadRequest);_=json.NewEncoder(w).Encode(APIResponse{Status:"error",Message:"CSV file is required"});return};reader:=csv.NewReader(file);reader.FieldsPerRecord=-1;insert,err:=userDB.Prepare(`INSERT INTO public.bulk_messages(user_id,target,message,status) VALUES(NULL,$1,$2,'queued')`);if err!=nil{w.WriteHeader(http.StatusInternalServerError);return};defer insert.Close();imported,skipped:=0,0;first:=true;for{rec,e:=reader.Read();if e==io.EOF{break};if e!=nil{skipped++;continue};if first{first=false;if len(rec)>0&&strings.EqualFold(strings.TrimSpace(rec[0]),"phone"){continue}};if len(rec)<3{skipped++;continue};phone:=strings.TrimSpace(strings.TrimPrefix(rec[0],"+"));message:=strings.TrimSpace(rec[1]);consent:=strings.ToLower(strings.TrimSpace(rec[2]));if consent!="yes"&&consent!="true"&&consent!="1"{skipped++;continue};if phone==""||message==""||len(phone)>20||len(message)>10000{skipped++;continue};if _,e=insert.Exec(phone,message);e!=nil{skipped++;continue};imported++};_=json.NewEncoder(w).Encode(map[string]any{"status":"success","imported":imported,"skipped":skipped,"message":"Global messages queued. Safety limits remain enforced per WhatsApp account."})}
func bulkMessageStatusHandler(w http.ResponseWriter,r *http.Request){enableCORS(w);w.Header().Set("Content-Type","application/json");if r.Method!=http.MethodGet{w.WriteHeader(http.StatusMethodNotAllowed);return};if err:=ensureBulkMessageTable();err!=nil{w.WriteHeader(http.StatusInternalServerError);return};var queued,sending,sent,failed int;_=userDB.QueryRow(`SELECT count(*) FROM public.bulk_messages WHERE user_id IS NULL AND status='queued'`).Scan(&queued);_=userDB.QueryRow(`SELECT count(*) FROM public.bulk_messages WHERE user_id IS NULL AND status='sending'`).Scan(&sending);_=userDB.QueryRow(`SELECT count(*) FROM public.bulk_messages WHERE user_id IS NULL AND status='sent'`).Scan(&sent);_=userDB.QueryRow(`SELECT count(*) FROM public.bulk_messages WHERE user_id IS NULL AND status='failed'`).Scan(&failed);devices:=make([]DeviceInfo,0);for _,uid:=range bulkConnectedDevices(){s:=getSession(uid);if s!=nil&&s.client!=nil&&s.client.Store!=nil&&s.client.Store.ID!=nil{devices=append(devices,DeviceInfo{UserID:uid,Phone:s.client.Store.ID.User,Connected:true,LoggedIn:true,State:"ready"})}};_=json.NewEncoder(w).Encode(map[string]any{"status":"success","queued":queued,"sending":sending,"sent":sent,"failed":failed,"connected_accounts":len(devices),"devices":devices})}
func nextBulkSender(allowed map[string]bool,offset int)string{ids:=make([]string,0,len(allowed));for id:=range allowed{ids=append(ids,id)};if len(ids)==0{return ""};return ids[offset%len(ids)]}
func claimBulkRow(uid string)(int64,string,string,bool){tx,err:=userDB.Begin();if err!=nil{return 0,"","",false};defer tx.Rollback();var id int64;var target,text string;err=tx.QueryRow(`SELECT id,target,message FROM public.bulk_messages WHERE user_id IS NULL AND status='queued' ORDER BY id FOR UPDATE SKIP LOCKED LIMIT 1`).Scan(&id,&target,&text);if err!=nil{return 0,"","",false};if _,err=tx.Exec(`UPDATE public.bulk_messages SET status='sending',attempts=attempts+1,assigned_sender=$1 WHERE id=$2`,uid,id);err!=nil{return 0,"","",false};if err=tx.Commit();err!=nil{return 0,"","",false};return id,target,text,true}
func markBulkFailed(id int64,msg string){_,_=userDB.Exec(`UPDATE public.bulk_messages SET status='failed',last_error=$1 WHERE id=$2`,msg,id)}
func processBulkMessagesGlobal(){if getAdminSetting("bulk_auto_send_enabled","false")!="true"{return};ids:=bulkConnectedDevices();if len(ids)==0{return};limit:=safeSettingInt("bulk_batch_size",5,1,20);allowed:=make(map[string]bool,len(ids));for _,uid:=range ids{allowed[uid]=true};for i:=0;i<limit;i++{uid:=nextBulkSender(allowed,i);id,target,text,ok:=claimBulkRow(uid);if !ok{return};s:=getSession(uid);if s==nil||s.client==nil{markBulkFailed(id,"WhatsApp account disconnected");continue};s.mu.Lock();err:=safeSendMessage(uid,s.client,types.JID{User:target,Server:types.DefaultUserServer},text);s.mu.Unlock();if err!=nil{markBulkFailed(id,err.Error());continue};_,_=userDB.Exec(`UPDATE public.bulk_messages SET status='sent',sent_at=now(),last_error=NULL WHERE id=$1`,id)}}
func bulkWorkerLoop(){for userDB==nil{time.Sleep(2*time.Second)};_=ensureBulkMessageTable();t:=time.NewTicker(time.Minute);defer t.Stop();for{processBulkMessagesGlobal();<-t.C}}
func init(){go bulkWorkerLoop()}
func bulkAdminPageHandler(w http.ResponseWriter,r *http.Request){if r.Method!=http.MethodGet{w.WriteHeader(http.StatusMethodNotAllowed);return};data:=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>88Task • Bulk Messages</title><style>*{box-sizing:border-box}body{font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#f5f6f7;color:#000;margin:0;min-height:100vh}.wrap{max-width:1100px;margin:auto;padding:24px 16px 50px}.top{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:20px}.back{color:#000;text-decoration:none;font-weight:800}.title{margin:0;font-size:30px;color:#000}.subtitle{margin:5px 0 0;color:#333}.card{background:#fff;border:1px solid #d9d9d9;border-radius:14px;padding:22px;margin:16px 0;box-shadow:0 2px 8px rgba(0,0,0,.06)}h2{font-size:19px;margin:0 0 8px;color:#000}.muted{color:#333;font-size:13px;line-height:1.55}b,strong,label,span,p{color:#000}.hint{background:#f1f1f1;border-left:4px solid #000;padding:12px;border-radius:7px;margin:14px 0;color:#000}.upload-row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}input[type=file]{font:inherit;color:#000;background:#fff;border:1px solid #aaa;border-radius:8px;padding:9px;max-width:100%}button{font:inherit;padding:11px 16px;border-radius:8px;border:1px solid #000;background:#000;color:#fff;font-weight:800;cursor:pointer}button.secondary{background:#fff;color:#000}button:disabled{opacity:.55;cursor:not-allowed}.stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}.stat{border:1px solid #ddd;border-radius:10px;padding:15px;background:#fafafa}.stat .num{display:block;font-size:24px;font-weight:850;margin-top:5px}.devices{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:10px;margin:15px 0}.device{display:block;border:1px solid #ccc;border-radius:10px;padding:14px;background:#fff;cursor:pointer}.device:hover{border-color:#000}.device input{margin-right:8px}.device small{color:#333;display:block;margin-top:6px}.actions{display:flex;gap:10px;flex-wrap:wrap}.statusbar{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:12px}.ok{font-weight:700}.error{font-weight:700}.format{width:100%;border-collapse:collapse;margin-top:12px}.format th,.format td{border:1px solid #ddd;padding:9px;text-align:left;color:#000}.format th{background:#f0f0f0}.footer-note{font-size:12px;color:#333;margin-top:15px}@media(max-width:700px){.stats{grid-template-columns:repeat(2,1fr)}.title{font-size:25px}.card{padding:17px}}@media(max-width:430px){.stats{grid-template-columns:1fr 1fr}.stats .stat:last-child{grid-column:1/-1}}</style></head><body><main class="wrap"><div class="top"><div><a class="back" href="/admin">← Admin</a><h1 class="title">Bulk Messages</h1><p class="subtitle">Global WhatsApp campaign management</p></div><button class="secondary" onclick="refresh()">Refresh</button></div><div class="card"><h2>1. Import Campaign Data</h2><p class="muted">Upload one large CSV file. No App User ID is required because this is a global queue.</p><div class="hint"><b>Required format:</b> phone,message,consent<br>Example: 919876543210,Hello from 88Task,yes<br>Only rows with consent <b>yes / true / 1</b> are queued.</div><div class="upload-row"><input id="file" type="file" accept=".csv,text/csv"><button id="uploadBtn" onclick="upload()">Import CSV</button></div><div id="msg" class="statusbar"><span class="muted">Ready for CSV upload.</span></div><table class="format"><tr><th>Column</th><th>Required</th><th>Description</th></tr><tr><td>phone</td><td>Yes</td><td>Recipient number with country code</td></tr><tr><td>message</td><td>Yes</td><td>Message text</td></tr><tr><td>consent</td><td>Yes</td><td>Must be yes, true, or 1</td></tr></table></div><div class="card"><h2>2. Manual Send</h2><p class="muted">Choose which connected WhatsApp accounts may process the global queue. If multiple accounts are selected, queued messages are distributed across them.</p><div id="devices" class="devices"></div><div class="actions"><button onclick="selectAll()" class="secondary">Select All</button><button onclick="clearAll()" class="secondary">Clear</button><button id="sendBtn" onclick="manualSend()">Send Selected</button></div><p class="footer-note">Safety controls, account limits, typing behavior and configured delays remain active. This page does not bypass platform safety controls.</p></div><div class="card"><h2>3. Queue Overview</h2><div class="stats"><div class="stat">Queued<span class="num" id="q">—</span></div><div class="stat">Sending<span class="num" id="sg">—</span></div><div class="stat">Sent<span class="num" id="s">—</span></div><div class="stat">Failed<span class="num" id="f">—</span></div><div class="stat">Connected Accounts<span class="num" id="c">—</span></div></div><div class="statusbar"><span id="updated" class="muted">Updating…</span><span id="auto" class="ok">Auto Send is controlled from Settings.</span></div></div></main><script>const token=sessionStorage.getItem('admin_token')||'';const H={'X-Admin-Token':token};async function api(u,o={}){o.headers=Object.assign({},H,o.headers||{});const r=await fetch(u,o);if(r.status===401||r.status===403){throw new Error('Admin authentication required')}return r.json()}function setMsg(text,cls='muted'){document.getElementById('msg').innerHTML='<span class="'+cls+'">'+text+'</span>'}async function upload(){const f=document.getElementById('file').files[0];if(!f){setMsg('Please select a CSV file first.','error');return}const btn=document.getElementById('uploadBtn');btn.disabled=true;setMsg('Importing '+f.name+'…');try{const fd=new FormData();fd.append('file',f);const d=await api('/admin/bulk/import',{method:'POST',body:fd});setMsg(d.message||('Imported '+(d.imported||0)+' rows; skipped '+(d.skipped||0)+'.'),'ok');document.getElementById('file').value='';refresh()}catch(e){setMsg(e.message,'error')}finally{btn.disabled=false}}async function manualSend(){const ids=[...document.querySelectorAll('#devices input:checked')].map(x=>x.value);if(!ids.length){setMsg('Select at least one connected WhatsApp account.','error');return}const btn=document.getElementById('sendBtn');btn.disabled=true;setMsg('Sending from selected accounts…');try{const d=await api('/admin/bulk/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'send',user_ids:ids,limit:200})});setMsg(d.message||('Attempted '+(d.attempted||0)+'; sent '+(d.sent||0)+'.'),'ok');refresh()}catch(e){setMsg(e.message,'error')}finally{btn.disabled=false}}function selectAll(){document.querySelectorAll('#devices input').forEach(x=>x.checked=true)}function clearAll(){document.querySelectorAll('#devices input').forEach(x=>x.checked=false)}async function refresh(){try{const d=await api('/admin/bulk/status');if(d.status!=='success')throw new Error(d.message||'Unable to load status');document.getElementById('q').textContent=d.queued;document.getElementById('sg').textContent=d.sending;document.getElementById('s').textContent=d.sent;document.getElementById('f').textContent=d.failed;document.getElementById('c').textContent=d.connected_accounts;const old=[...document.querySelectorAll('#devices input:checked')].map(x=>x.value);document.getElementById('devices').innerHTML=(d.devices||[]).map(x=>'<label class="device"><input type="checkbox" value="'+x.user_id+'" '+(old.includes(x.user_id)?'checked':'')+'> <b>+'+x.phone+'</b><small>App User: '+x.user_id+' • Connected</small></label>').join('')||'<div class="muted">No connected WhatsApp accounts are available.</div>';document.getElementById('updated').textContent='Last updated: '+new Date().toLocaleTimeString()}catch(e){document.getElementById('updated').textContent=e.message;document.getElementById('updated').className='error'}}refresh();setInterval(refresh,10000)</script></body></html>`;w.Header().Set("Cache-Control","private, max-age=10");w.Header().Set("Content-Type","text/html; charset=utf-8");_,_=w.Write([]byte(data))}
